javas.java:

int def educationScore(str:education) {
    if (education == "DOCTOR") {
        return 40;
    } else if (education == "MASTER") {
        return 30;
    } else if (education == "BACHELOR") {
        return 20;
    } else if (education == "COLLEGE") {
        return 10;
    } else {
        return 0;
    }
}


int def securityScore(int:months) {
    if (months >= 48) {
        return 40;
    } else if (months >= 36) {
        return 30;
    } else if (months >= 24) {
        return 20;
    } else if (months >= 12) {
        return 10;
    } else {
        return 0;
    }
}


int def ageSettleScore(int:age) {
    if (age <= 35) {
        return 15;
    } else if (age <= 45) {
        return 10;
    } else if (age <= 55) {
        return 5;
    } else {
        return 0;
    }
}


int def titleScore(str:talentTitle) {
    if (talentTitle == "TOP_TALENT") {
        return 30;
    } else if (talentTitle == "ELITE") {
        return 15;
    } else {
        return 0;
    }
}


int def investTaxScore(double:enterpriseTaxWan) {
    if (enterpriseTaxWan >= 100.0) {
        return 20;
    } else if (enterpriseTaxWan >= 50.0) {
        return 10;
    } else if (enterpriseTaxWan >= 10.0) {
        return 5;
    } else {
        return 0;
    }
}


str def settleResult(int:points) {
    if (points >= 80) {
        return "APPROVE";
    } else if (points >= 60) {
        return "REVIEW";
    } else {
        return "REJECT";
    }
}


boolean def houseEligible(int:ssMonths, int:taxMonths, str:talentTitle) {
    boolean eligible = false;
    if (ssMonths >= 36 || taxMonths >= 36) {
        eligible = true;
    }
    if (talentTitle == "TOP_TALENT") {
        if (ssMonths >= 3 || taxMonths >= 3) {
            eligible = true;
        }
    }
    if (talentTitle == "ELITE") {
        if (ssMonths >= 3 || taxMonths >= 3) {
            eligible = true;
        }
    }
    return eligible;
}


boolean def carEligible(int:ssMonths, int:taxMonths, boolean:noCarInCity, str:talentTitle) {
    boolean eligible = false;
    if (noCarInCity) {
        if (ssMonths >= 24 || taxMonths >= 24) {
            eligible = true;
        }
        if (talentTitle == "TOP_TALENT") {
            if (ssMonths >= 6 || taxMonths >= 6) {
                eligible = true;
            }
        }
        if (talentTitle == "ELITE") {
            if (ssMonths >= 6 || taxMonths >= 6) {
                eligible = true;
            }
        }
    }
    return eligible;
}
